/**
 * Factory Energy System – Extended
 * - Numerical-condition centric checks
 * - Policy thresholds (max usage, min efficiency, peak-hour multipliers)
 * - Anomaly detection (negative/zero inputs, extreme ratio, surge)
 * - Rolling stats (mean/median/min/max/p95)
 * - Log & CSV export
 * - Reproducible simulation (seed)
 * - Test toggles: VT / FT / Z3 / UVT
 *
 * Only one public class; other helpers are package-private.
 */
public class c118_FactoryEnergySystemEx {

    // ======== Toggle switches for test groups ========
    private static final boolean RUN_VT  = false; 
    private static final boolean RUN_FT  = false;  
    private static final boolean RUN_Z3  = false; 
    private static final boolean RUN_UVT = true;  

    // ======== Console verbosity ========
    private static final boolean VERBOSE_CONSOLE = true;

    public static void main(String[] args) {
        EnergyPolicy policy = new EnergyPolicy(
                1000.0,   // maxAllowedUsage (kWh)
                0.50,     // minEfficiency (units/kWh)
                1.30,     // peakHourMultiplier threshold factor
                18, 21    // peak hours [start, end)
        );

        EnergyMonitorEx monitor = new EnergyMonitorEx(policy);

        // Handful quick demos (you can comment them out)
        monitor.recordUsage(800.0, 1200.0, 10); // ok
        monitor.recordUsage(1200.0, 400.0, 19); // overuse in peak
        monitor.recordUsage(-10.0, 200.0, 9);   // invalid

        // ======== Execute test groups ========
//        if (RUN_VT)  TestSuites.runVT(monitor);
//        if (RUN_FT)  TestSuites.runFT(monitor);
//        if (RUN_Z3)  TestSuites.runZ3(monitor);
//        if (RUN_UVT) TestSuites.runUVT(monitor);
        
        TestSuites.runVT(monitor);
//        TestSuites.runFT(monitor);
//        TestSuites.runZ3(monitor);
//        TestSuites.runUVT(monitor);

        // ======== Print and export ========
        monitor.printEnergyLog();

        EnergyStats stats = monitor.computeStats();
        if (VERBOSE_CONSOLE) {
            System.out.println("\n=== Summary Statistics ===");
            System.out.printf(Locale.US, "count=%d, totalEnergy=%.2f kWh, totalOutput=%.2f units%n",
                    stats.count, stats.totalEnergy, stats.totalOutput);
            System.out.printf(Locale.US, "efficiencyMean=%.4f, min=%.4f, max=%.4f, p95=%.4f%n",
                    stats.meanEfficiency, stats.minEfficiency, stats.maxEfficiency, stats.p95Efficiency);
        }

        try {
            String csv = "energy_log_c118.csv";
            monitor.exportCsv(csv);
            if (VERBOSE_CONSOLE) {
                System.out.println("CSV exported: " + csv);
            }
        } catch (IOException e) {
            System.out.println("Failed to export CSV: " + e.getMessage());
        }
    }
}

// =================== Core Classes ===================

/** Policy & thresholds for energy usage. */
class EnergyPolicy {
    final double maxAllowedUsage;    // kWh
    final double minEfficiency;      // units/kWh
    final double peakHourMultiplier; // factor if usage in peak hours
    final int peakStartHour;         // inclusive
    final int peakEndHour;           // exclusive

    EnergyPolicy(double maxAllowedUsage, double minEfficiency,
                 double peakHourMultiplier, int peakStartHour, int peakEndHour) {
        this.maxAllowedUsage = maxAllowedUsage;
        this.minEfficiency = minEfficiency;
        this.peakHourMultiplier = peakHourMultiplier;
        this.peakStartHour = peakStartHour;
        this.peakEndHour = peakEndHour;
    }

    boolean isPeakHour(int hour0to23) {
        if (peakStartHour <= peakEndHour) {
            return hour0to23 >= peakStartHour && hour0to23 < peakEndHour;
        }
        // wrap-around case (not used here)
        return hour0to23 >= peakStartHour || hour0to23 < peakEndHour;
    }
}

/** Single usage record. */
class EnergyUsageRecord {
    final double energyUsed;
    final double productionOutput;
    final double efficiency;     // units/kWh
    final int hourOfDay;         // 0-23
    final String message;        // formatted line
    final List<String> warnings; // triggered warnings

    EnergyUsageRecord(double e, double p, int hour, double eff, String msg, List<String> warns) {
        this.energyUsed = e;
        this.productionOutput = p;
        this.efficiency = eff;
        this.hourOfDay = hour;
        this.message = msg;
        this.warnings = warns;
    }
}

/** Anomaly/Rule detector (pure numerical rules). */
class EnergyAnomalyDetector {

    static List<String> detect(EnergyPolicy policy,
                               double energyUsed, double productionOutput,
                               double efficiency, int hourOfDay,
                               EnergyUsageRecord prev) {
        List<String> warns = new ArrayList<>();

        // 1) Invalid input guards
        if (energyUsed <= 0) warns.add("Invalid: energyUsed <= 0");
        if (productionOutput <= 0) warns.add("Invalid: productionOutput <= 0");

        // 2) Overuse vs policy
        if (energyUsed > policy.maxAllowedUsage) {
            warns.add("WARNING: Energy overuse (> maxAllowedUsage)");
        }

        // 3) Low efficiency
        if (efficiency < policy.minEfficiency) {
            warns.add("WARNING: Low efficiency (< minEfficiency)");
        }

        // 4) Peak-hour stress (scaled condition)
        if (policy.isPeakHour(hourOfDay) && energyUsed > policy.maxAllowedUsage / policy.peakHourMultiplier) {
            warns.add("WARNING: Overuse during peak hour");
        }

        // 5) Extreme ratio (output/energy unusually high)
        if (efficiency > policy.minEfficiency * 200) {
            warns.add("WARNING: Suspiciously high efficiency");
        }

        // 6) Surge detection vs previous record (if available)
        if (prev != null) {
            if (energyUsed > prev.energyUsed * 2.5) warns.add("Surge: energyUsed spiked > 2.5x");
            if (productionOutput < prev.productionOutput * 0.4) warns.add("Drop: productionOutput fell < 0.4x");
        }

        return warns;
    }
}

